        margin: 0;
        font-family:DM Sans, sans-serif
    }

    button, input, select, textarea {
        font:inherit
    }

    button, a {
        -webkit-tap-highlight-color:transparent
    }

    a {
        color: inherit;
        text-decoration:none
    }

    h1, h2, h3, p {
        margin:0
    }
}

@layer utilities {
    .fixed {
        position:fixed
    }

    .static {
        position:static
    }

    .start {
        inset-inline-start:var(--spacing)
    }

    .container {
        width:100%
    }

    @media (width > =40rem) {
        .container {
            max-width:40rem
        }
    }

    @media (width > =48rem) {
        .container {
            max-width:48rem
        }
    }

    @media (width > =64rem) {
        .container {
            max-width:64rem
        }
    }

    @media (width > =80rem) {
        .container {
            max-width:80rem
        }
    }

    @media (width > =96rem) {
        .container {
            max-width:96rem
        }
    }

    .grid {
        display:grid
    }

    .hidden {
        display:none
    }

    .inline {
        display:inline
    }

    .transform {
