    }

    .filter {
        filter:var(--tw-blur,) var(--tw-brightness,) var(--tw-contrast,) var(--tw-grayscale,) var(--tw-hue-rotate,) var(--tw-invert,) var(--tw-saturate,) var(--tw-sepia,) var(--tw-drop-shadow,)
    }
}

:root {
    --navy: #0a3044;
    --navy-deep: #062536;
    --blue: #2169b1;
    --blue-light: #eaf3fb;
    --yellow: #ffe94a;
    --ink: #0b2d3f;
    --body: #445866;
    --line: #d9e3e8;
    --mist: #f3f7fa;
    --white:#fff
}

html {
    scroll-behavior:smooth
}

* {
    box-sizing:border-box
}

.site-shell {
    min-height: 100vh;
    overflow:hidden
}

.container {
    width: min(1160px, 100% - 48px);
    margin-inline:auto
}

.header {
    z-index: 50;
    color: #fff;
    background: var(--navy);
    border-bottom: 2px solid var(--yellow);
    position:relative
}

.nav-wrap {
    justify-content: space-between;
    align-items: center;
    height: 84px;
    display:flex
}

.brand {
    flex-shrink: 0;
    align-items: center;
    gap: 11px;
    display:inline-flex
}

.brand > span:last-child {
    flex-direction: column;
    line-height: 1;
    display:flex
}

.brand strong {
    color: #fff;
    letter-spacing: .07em;
    font-family: Manrope, sans-serif;
    font-size: 23px;
    font-weight:800
}

.brand small {
    color: #a9c3d1;
    letter-spacing: .26em;
    margin-top: 5px;
    font-size: 16px;
    font-weight:700
}

.brand-mark {
    background: var(--yellow);
    border-radius: 48% 52% 52% 48%/22% 22% 78% 78%;
    width: 36px;
    height: 44px;
    display: block;
    position: relative;
    transform:rotate(-8deg)
}

.brand-mark:after {
    content: "";
    background: var(--blue);
    border-radius: 50% 40% 55% 45%;
    position: absolute;
    inset:7px 4px 5px 17px
}

.brand-mark span {
    z-index: 2;
    background: var(--navy);
    border-radius: 0 0 80% 50%;
    width: 18px;
    height: 17px;
    position: absolute;
    top: -2px;
    left: 12px;
    transform:rotate(12deg)
}

.nav-links, .nav-actions {
    align-items: center;
    display:flex
}

.nav-links {
    gap: 28px;
    margin-left: auto;
    margin-right:30px
}

.nav-links > a {
    color: #d7e4ea;
    font-size: 16px;
    font-weight: 600;
    transition:color .2s
}

.nav-links > a:hover, .phone-link:hover {
    color:var(--yellow)
}

.nav-actions {
    gap:18px
}

.phone-link {
    color: #fff;
    align-items: center;
    gap: 8px;
    font-size: 16px;
    font-weight: 700;
    display:inline-flex
}

.mobile-call, .menu-button {
    display:none
}

.button {
    cursor: pointer;
    border: 1px solid #0000;
    border-radius: 4px;
    justify-content: center;
    align-items: center;
    gap: 10px;
    min-height: 52px;
    padding: 0 24px;
    font-size: 16px;
    font-weight: 700;
    transition: transform .2s, box-shadow .2s, background .2s;
    display:inline-flex
}

.button:hover {
    transform:translateY(-2px)
}

.button-yellow {
    color: var(--navy-deep);
    background: var(--yellow);
    box-shadow:0 8px 24px #0a304424
}

.button-yellow:hover {
    background: #fff36e;
    box-shadow:0 10px 28px #0a304438
}

.button-navy {
    color: #fff;
    background:var(--navy)
}

.button-small {
    min-height: 42px;
    padding-inline: 18px;
    font-size:16px
}

.hero {
    background: radial-gradient(circle at 77% 35%, #2169b11a, #0000 30%), linear-gradient(135deg, #f1f6fa 0%, #fff 58%);
    min-height: 700px;
    padding-top: 88px;
    position:relative
}

.hero:before {
    content: "";
    border: 1px solid #2169b11a;
    border-radius: 50%;
    width: 450px;
    height: 450px;
    position: absolute;
    top: 66px;
    right:-130px
}

.hero-grid {
    grid-template-columns: 1.02fr .98fr;
    align-items: center;
    gap: 56px;
    display: grid;
    position:relative
}

.eyebrow {
    color: var(--blue);
    letter-spacing: .16em;
    text-transform: uppercase;
    align-items: center;
    gap: 11px;
    margin-bottom: 20px;
    font-size: 16px;
    font-weight: 800;
    line-height: 1.2;
    display:flex
}

.eyebrow span {
    background: currentColor;
    width: 27px;
    height:2px
}

.hero h1, .section-heading h2, .split-heading h2, .contact-copy h2 {
    letter-spacing: -.045em;
    font-family: Manrope, sans-serif;
    line-height:1.07
}

.hero h1 {
    max-width: 620px;
    font-size: clamp(47px, 5vw, 70px);
    font-weight:700
}

h1 em, h2 em {
    color: var(--blue);
    font-style: normal;
    position:relative
}

.hero h1 em:after {
    content: "";
    background: url("data:image/svg+xml,%3Csvg width='220' height='8' viewBox='0 0 220 8' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M2 6C58 1 144 1 218 4' fill='none' stroke='%23ffe94a' stroke-width='5' stroke-linecap='round'/%3E%3C/svg%3E") 50%/100% 100% no-repeat;
    width: 100%;
    height: 8px;
    position: absolute;
    bottom: -5px;
    left:0
}

.hero-sub {
    max-width: 540px;
    color: var(--body);
    margin-top: 26px;
    font-size: 19px;
    line-height:1.6
}

.hero-actions {
    align-items: center;
    gap: 25px;
    margin-top: 32px;
    display:flex
}

.text-link {
    color: var(--blue);
    cursor: pointer;
    background: 0 0;
    border: 0;
    align-items: center;
    gap: 8px;
    font-weight: 700;
    display:inline-flex
}

.text-link:hover {
    color:var(--navy)
}

.hero-proof {
    align-items: center;
    gap: 14px;
    margin-top: 32px;
    display:flex
}

.avatar-stack {
    display:flex
}

.avatar-stack span, .person-avatar {
    color: #fff;
    background: var(--blue);
    border: 2px solid #fff;
    border-radius: 50%;
    place-items: center;
    width: 36px;
    height: 36px;
    font-size: 16px;
    font-weight: 800;
    display:grid
}

.avatar-stack span + span {
    margin-left:-9px
}

.avatar-stack span:nth-child(2) {
    background:#7d9cb2
}

.avatar-stack span:nth-child(3) {
    background:var(--navy)
}

.stars {
    color: #e9b90e;
    letter-spacing: .08em;
    font-size:16px
}

.hero-proof p {
    color: var(--body);
    margin-top: 3px;
    font-size:16px
}

.hero-visual {
    place-items: center;
    min-height: 480px;
    display: grid;
    position:relative
}

.orbit {
    border: 1px solid #2169b126;
    border-radius: 50%;
    position:absolute
}

.orbit-one {
    width: 450px;
    height:450px
}

.orbit-two {
    border-style: dashed;
    width: 350px;
    height:350px
}

.dashboard-card {
    z-index: 2;
    color: #fff;
    background: var(--navy);
    border: 5px solid #fff;
    border-radius: 15px;
    width: 390px;
    position: relative;
    overflow: hidden;
    transform: rotate(1.5deg);
    box-shadow:0 30px 65px #082f4440
}

.dashboard-top {
    border-bottom: 1px solid #ffffff1a;
    justify-content: space-between;
    align-items: center;
    height: 48px;
    padding-inline: 17px;
    font-size: 16px;
    font-weight: 700;
    display:flex
}

.dashboard-top span {
    align-items: center;
    gap: 7px;
    display:flex
}

.dashboard-top i {
    background: var(--yellow);
    border-radius: 50%;
    width: 7px;
    height: 7px;
    display:block
}

.dashboard-top small {
    color: var(--yellow);
    background: #ffe94a1f;
    border-radius: 20px;
    padding:4px 8px
}

.dashboard-body {
    padding:22px
}

.dashboard-heading {
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    display:flex
}

.dashboard-heading span, .status-card > span:nth-child(2), .help-card > span:nth-child(2), .uptime span {
    flex-direction: column;
    display:flex
}

.dashboard-heading small, .hero-card small, .uptime small {
    color: #9db8c7;
    margin-bottom: 4px;
    font-size:16px
}

.dashboard-heading strong {
    font-size:20px
}

.score-ring {
    border: 5px solid var(--yellow);
    border-right-color: #ffffff29;
    border-radius: 50%;
    place-items: center;
    width: 54px;
    height: 54px;
    font-weight: 800;
    display:grid
}

.health-row {
    background: #ffffff0e;
    border-radius: 6px;
    justify-content: space-between;
    align-items: center;
    margin-top: 8px;
    padding: 11px 13px;
    font-size: 16px;
    display:flex
}

.health-row span {
    align-items: center;
    gap: 9px;
    display:flex
}

.health-row svg {
    color: #8cbce2;
    width:15px
}

.health-row b {
    color: #a5d8bb;
    font-size:16px
}

.uptime {
    justify-content: space-between;
    align-items: flex-end;
    margin-top: 18px;
    display:flex
}

.uptime strong {
    color: var(--yellow);
    font-size:20px
}

.uptime > div {
    align-items: flex-end;
    gap: 5px;
    height: 40px;
    display:flex
}

.uptime i {
    background: var(--blue);
    border-radius: 2px 2px 0 0;
    width: 8px;
    display:block
}

.uptime i:first-child {
    height:16px
}

.uptime i:nth-child(2) {
    height:23px
}

.uptime i:nth-child(3) {
    height:20px
}

.uptime i:nth-child(4) {
    height:29px
}

.uptime i:nth-child(5) {
    height:25px
}

.uptime i:nth-child(6) {
    background: var(--yellow);
    height:34px
}

.uptime i:nth-child(7) {
    height:31px
}

.uptime i:nth-child(8) {
    background: var(--yellow);
    height:38px
}

.hero-card {
    z-index: 4;
    background: #fff;
    border-radius: 8px;
    align-items: center;
    gap: 11px;
    padding: 14px;
    display: flex;
    position: absolute;
    box-shadow:0 16px 35px #082f442e
}

.hero-card strong {
    white-space: nowrap;
    font-size:16px
}

.status-card {
    top: 55px;
    right:-12px
}

.help-card {
    bottom: 50px;
    left:-12px
}

.status-icon, .help-icon {
    width: 36px;
    height: 36px;
    color: var(--blue);
    background: var(--blue-light);
    border-radius: 6px;
    place-items: center;
    display:grid
}

.status-icon svg, .help-icon svg {
    width:19px
}

.help-icon {
    color: var(--navy);
    background:var(--yellow)
}

.status-check {
    color: #2c9b67;
    width: 17px;
    margin-left:5px
}

.hero-stats {
    z-index: 3;
    border: 1px solid var(--line);
    background: #fff;
    grid-template-columns: repeat(4, 1fr);
    margin-top: 85px;
    display: grid;
    position: relative;
    box-shadow:0 10px 40px #082f440f
}

.hero-stats div {
    flex-direction: column;
    padding: 24px 28px;
    display:flex
}

.hero-stats div + div {
    border-left:1px solid var(--line)
}

.hero-stats strong {
    font:800 24px Manrope, sans-serif
}

.hero-stats span {
    color: var(--body);
    margin-top: 5px;
    font-size:16px
}

.section {
    padding:110px 0
}

.video-section {
    background: #fff;
    padding-top:130px
}

.section-heading h2, .split-heading h2, .contact-copy h2 {
    font-size: clamp(38px, 4vw, 53px);
    font-weight:700
}

.section-heading > p:last-child {
    max-width: 610px;
    color: var(--body);
    margin-top: 22px;
    font-size: 17px;
    line-height:1.65
}

.section-heading.centered {
    text-align:center
}

.section-heading.centered .eyebrow {
    justify-content:center
}

.section-heading.centered > p:last-child {
    margin-inline:auto
}

.video-frame {
    background: var(--navy);
    cursor: pointer;
    border: 8px solid #fff;
    border-radius: 12px;
    width: min(930px, 100%);
    height: 520px;
    margin: 52px auto 0;
    padding: 0;
    display: block;
    position: relative;
    overflow: hidden;
    box-shadow:0 24px 65px #082f4433
}

.video-frame img {
    object-fit: cover;
    width: 100%;
    height: 100%;
    display:block
}

.video-overlay {
    background: linear-gradient(#06253608 40%, #062536d1);
    position: absolute;
    inset:0
}

.play-button {
    width: 80px;
    height: 80px;
    color: var(--navy);
    background: var(--yellow);
    background-clip: padding-box;
    border: 7px solid #ffffff47;
    border-radius: 50%;
    place-items: center;
    transition: transform .25s;
    display: grid;
    position: absolute;
    top: 50%;
    left: 50%;
    transform:translate(-50%, -50%)
}

.video-frame:hover .play-button {
    transform:translate(-50%, -50%)scale(1.08)
}

.play-button svg {
    width: 28px;
    margin-left:4px
}

.video-notice {
    width: min(390px, 100% - 40px);
    color: var(--navy);
    background: #fffffff5;
    border-radius: 8px;
    flex-direction: column;
    align-items: center;
    padding: 24px;
    display: flex;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    box-shadow:0 18px 45px #06253640
}

.video-notice svg {
    width: 28px;
    height: 28px;
    color: var(--blue);
    margin-bottom:10px
}

.video-notice strong {
    font:700 18px Manrope, sans-serif
}

.video-notice small {
    max-width: 310px;
    color: var(--body);
    margin-top: 7px;
    font-size: 16px;
    line-height:1.5
}

.video-caption {
    text-align: left;
    color: #fff;
    flex-direction: column;
    display: flex;
    position: absolute;
    bottom: 28px;
    left:32px
}

.video-caption small {
    color: var(--yellow);
    text-transform: uppercase;
    letter-spacing: .13em;
    margin-bottom: 5px;
    font-size: 16px;
    font-weight:800
}

.video-caption strong {
    font:700 20px Manrope, sans-serif
}

.placeholder-note {
    color: #788b97;
    text-align: center;
    margin-top: 18px;
    font-size:16px
}

.proof-section {
    background: var(--mist);
    border-block: 1px solid #e6edf1;
    padding:74px 0 110px
}

.trusted-label {
    color: #6f838f;
    letter-spacing: .16em;
    text-align: center;
    text-transform: uppercase;
    margin-bottom: 30px;
    font-size: 16px;
    font-weight:800
}

.logo-row {
    color: #5d7786;
    grid-template-columns: repeat(5, 1fr);
    align-items: center;
    display:grid
}

.logo-row > span {
    opacity: .76;
    justify-content: center;
    align-items: center;
    gap: 8px;
    font: 700 16px Manrope, sans-serif;
    display:flex
}

.logo-row svg {
    width:21px
}

.eagle-mark, .curve-mark {
    color: #fff;
    background: #5d7786;
    border-radius: 50%;
    place-items: center;
    width: 24px;
    height: 24px;
    font-size: 16px;
    display:grid
}

.curve-mark {
    border-radius: 7px 50% 50%;
    transform:rotate(-12deg)
}

.testimonial-grid {
    grid-template-columns: 1.45fr .85fr;
    gap: 24px;
    margin-top: 68px;
    display:grid
}

.testimonial-featured, .testimonial-mini {
    border: 1px solid var(--line);
    background: #fff;
    border-radius: 8px;
    padding:38px
}

.testimonial-featured > svg {
    width: 34px;
    height: 34px;
    color: var(--blue);
    fill:var(--blue-light)
}

.testimonial-featured blockquote {
    letter-spacing: -.02em;
    max-width: 760px;
    margin: 22px 0 30px;
    font:600 24px/1.5 Manrope, sans-serif
}

.testimonial-featured footer, .testimonial-mini footer {
    align-items: center;
    gap: 12px;
    display:flex
}

.testimonial-featured footer span:nth-child(2), .testimonial-mini footer span:nth-child(2) {
    flex-direction: column;
    display:flex
}

.testimonial-featured footer strong, .testimonial-mini footer strong {
    font-size:16px
}

.testimonial-featured footer small, .testimonial-mini footer small {
    color: #738692;
    margin-top: 3px;
    font-size:16px
}

.testimonial-featured footer .stars {
    margin-left:auto
}

.person-avatar {
    width: 42px;
    height:42px
}

.person-avatar.yellow {
    color: var(--navy);
    background:var(--yellow)
}

.testimonial-mini {
    flex-direction: column;
    justify-content: center;
    display:flex
}

.testimonial-mini > p {
    margin: 18px 0 30px;
    font:600 18px/1.55 Manrope, sans-serif
}

.steps-section {
    background:#fff
}

.split-heading {
    grid-template-columns: 1fr .65fr;
    align-items: end;
    gap: 80px;
    display:grid
}

.split-heading > p {
    color: var(--body);
    padding-bottom: 7px;
    font-size: 17px;
    line-height:1.65
}

.steps-grid {
    border: 1px solid var(--line);
    grid-template-columns: repeat(4, 1fr);
    margin-top: 64px;
    display:grid
}

.step-card {
    background: #fff;
    min-height: 345px;
    padding: 34px 27px;
    position: relative;
    overflow:hidden
}

.step-card + .step-card {
    border-left:1px solid var(--line)
}

.step-card:after {
    content: "";
    background: var(--blue);
    transform-origin: 0;
    height: 4px;
    transition: transform .3s;
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    transform:scaleX(0)
}

.step-card:hover:after {
    transform:scaleX(1)
}

.step-number {
    color: #edf2f4;
    font: 800 54px Manrope, sans-serif;
    position: absolute;
    top: 12px;
    right:17px
}

.step-icon {
    width: 54px;
    height: 54px;
    color: var(--blue);
    background: var(--blue-light);
    border-radius: 8px;
    place-items: center;
    margin-top: 34px;
    display:grid
}

.step-icon svg {
    width:25px
}

.step-card h3 {
    margin-top: 26px;
    font:700 19px/1.25 Manrope, sans-serif
}

.step-card p {
    color: var(--body);
    margin-top: 13px;
    font-size: 16px;
    line-height:1.65
}

.steps-cta {
    background: var(--blue-light);
    justify-content: space-between;
    align-items: center;
    padding: 25px 28px;
    display:flex
}

.steps-cta p {
    color: #365362;
    align-items: center;
    gap: 10px;
    font-size: 16px;
    display:flex
}

.steps-cta p svg {
    width: 18px;
    color:var(--blue)
}

.studies-section {
    color: #fff;
    background:var(--navy)
}

.eyebrow.light {
    color:#7fb5e2
}

.studies-section .section-heading h2 em {
    color:var(--yellow)
}

.studies-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 22px;
    margin-top: 58px;
    display:grid
}

.study-card {
    min-height: 470px;
    color: var(--ink);
    background: #fff;
    border-radius: 8px;
    flex-direction: column;
    transition: transform .25s;
    display: flex;
    overflow:hidden
}

.study-card:hover {
    transform:translateY(-6px)
}

.study-top {
    letter-spacing: .1em;
    text-transform: uppercase;
    justify-content: space-between;
    align-items: center;
    padding: 22px 24px;
    font-size: 16px;
    font-weight: 800;
    display:flex
}

.study-top svg {
    width:19px
}

.study-result {
    color: #fff;
    background: var(--blue);
    align-items: flex-end;
    gap: 13px;
    min-height: 155px;
    padding: 24px;
    display:flex
}

.study-result strong {
    letter-spacing: -.05em;
    font:800 55px/1 Manrope, sans-serif
}

.study-result span {
    max-width: 100px;
    padding-bottom: 5px;
    font-size: 16px;
    line-height:1.25
}

.study-card.yellow .study-result {
    color: var(--navy);
    background:var(--yellow)
}

.study-card.navy .study-result {
    background:#071f2e
}

.study-copy {
    flex-direction: column;
    flex: 1;
    padding: 27px 24px 25px;
    display:flex
}

.study-copy h3 {
    font:700 19px/1.35 Manrope, sans-serif
}

.study-copy p {
    color: var(--body);
    margin-top: 13px;
    font-size: 16px;
    line-height:1.6
}

.study-copy a {
    color: var(--blue);
    align-items: center;
    gap: 7px;
    margin-top: auto;
    padding-top: 20px;
    font-size: 16px;
    font-weight: 800;
    display:inline-flex
}

.contact-section {
    background: #f1f6f9;
    position:relative
}

.contact-section:before {
    content: "";
    background: var(--yellow);
    width: 38%;
    height: 5px;
    position: absolute;
    top: 0;
    left:0
}

.contact-grid {
    grid-template-columns: .85fr 1.15fr;
    align-items: center;
    gap: 90px;
    display:grid
}

.contact-copy > p:nth-of-type(2) {
    color: var(--body);
    margin-top: 24px;
    font-size: 16px;
    line-height:1.7
}

.contact-copy ul {
    gap: 13px;
    margin: 28px 0 0;
    padding: 0;
    list-style: none;
    display:grid
}

.contact-copy li {
    color: #365261;
    align-items: center;
    gap: 11px;
    font-size: 16px;
    display:flex
}

.contact-copy li svg {
    color: #fff;
    background: var(--blue);
    border-radius: 50%;
    width: 19px;
    height: 19px;
    padding:3px
}

.contact-direct {
    border-top: 1px solid var(--line);
    align-items: center;
    gap: 13px;
    margin-top: 38px;
    padding-top: 28px;
    display:flex
}

.contact-direct > span {
    width: 44px;
    height: 44px;
    color: var(--navy);
    background: var(--yellow);
    border-radius: 50%;
    place-items: center;
    display:grid
}

.contact-direct svg {
    width:20px
}

.contact-direct p {
    flex-direction: column;
    display:flex
}

.contact-direct small {
    color: #6d818d;
    font-size:16px
}

.contact-direct a {
    margin-top: 3px;
    font:800 18px Manrope, sans-serif
}

.contact-faq {
    border: 1px solid var(--line);
    background: #fff;
    border-radius: 9px;
    padding: 40px 42px 24px;
    box-shadow:0 24px 60px #082f441a
}

.contact-faq .eyebrow {
    margin-bottom:12px
}

.faq-item {
    border-top:1px solid var(--line)
}

.faq-item:last-child {
    border-bottom:1px solid var(--line)
}

.faq-item button {
    width: 100%;
    color: var(--ink);
    text-align: left;
    cursor: pointer;
    background: 0 0;
    border: 0;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
    padding: 25px 0;
    font: 700 17px Manrope, sans-serif;
    display:flex
}

.faq-item button svg {
    flex: none;
    width: 19px;
    transition:transform .25s
}

.faq-item.is-open button {
    color:var(--blue)
}

.faq-item.is-open button svg {
    transform:rotate(180deg)
}

.faq-answer {
    grid-template-rows: 0fr;
    transition: grid-template-rows .3s;
    display:grid
}

.faq-answer p {
    color: var(--body);
    font-size: 16px;
    line-height: 1.7;
    overflow:hidden
}

.faq-item.is-open .faq-answer {
    grid-template-rows:1fr
}

.faq-item.is-open .faq-answer p {
    padding:0 40px 25px 0
}

.footer {
    color: #fff;
    background: var(--navy-deep);
    padding:62px 0 26px
}

.footer-top {
    grid-template-columns: 1fr auto auto;
    align-items: center;
    gap: 60px;
    display:grid
}

.footer-top > div:first-child > p {
    color: #9bb2bf;
    margin-top: 14px;
    font-size:16px
}

.footer-links {
    color: #c7d6de;
    gap: 28px;
    font-size: 16px;
    font-weight: 600;
    display:flex
}

.footer-links a:hover {
    color:var(--yellow)
}

.footer-bottom {
    color: #7f9aa9;
    border-top: 1px solid #ffffff1f;
    justify-content: space-between;
    margin-top: 48px;
    padding-top: 23px;
    font-size: 16px;
    display:flex
}

.footer-bottom p:last-child {
    gap: 18px;
    display:flex
}

@media (width<=1050px) {
    .phone-link {
        display:none
    }

    .nav-links {
        gap: 20px;
        margin-right:20px
    }

    .hero-grid {
        gap:20px
    }

    .dashboard-card {
        width:350px
    }

    .status-card {
        right:-6px
    }

    .help-card {
        left:-8px
    }

    .steps-grid {
        grid-template-columns:repeat(2, 1fr)
    }

    .step-card:nth-child(3) {
        border-left: 0;
        border-top:1px solid var(--line)
    }

    .step-card:nth-child(4) {
        border-top:1px solid var(--line)
    }

    .contact-grid {
        gap:50px
    }
}

@media (width<=820px) {
    .container {
        width:min(100% - 34px, 680px)
    }

    .nav-wrap {
        height:72px
    }

    .nav-actions .button {
        display:none
    }

    .menu-button {
        color: #fff;
        background: #ffffff14;
        border: 0;
        border-radius: 4px;
        place-items: center;
        width: 42px;
        height: 42px;
        display:grid
    }

    .menu-button svg {
        width:22px
    }

    .nav-links {
        background: var(--navy);
        flex-direction: column;
        align-items: stretch;
        gap: 0;
        max-height: 0;
        margin: 0;
        padding: 0 24px;
        transition: max-height .3s, padding .3s;
        display: flex;
        position: absolute;
        top: 72px;
        left: 0;
        right: 0;
        overflow:hidden
    }

    .nav-links.is-open {
        border-bottom: 2px solid var(--yellow);
        max-height: 390px;
        padding-block:14px 24px
    }

    .nav-links > a {
        border-bottom: 1px solid #ffffff14;
        padding:13px 0
    }

    .nav-links .mobile-call {
        color: var(--yellow);
        border-bottom: 0;
        align-items: center;
        gap: 9px;
        display:flex
    }

    .hero {
        padding-top:70px
    }

    .hero-grid {
        grid-template-columns:1fr
    }

    .hero-copy {
        text-align:center
    }

    .hero .eyebrow, .hero-actions, .hero-proof {
        justify-content:center
    }

    .hero-sub {
        margin-inline:auto
    }

    .hero-visual {
        min-height: 465px;
        margin-top:28px
    }

    .hero-stats {
        grid-template-columns: 1fr 1fr;
        margin-top:30px
    }

    .hero-stats div:nth-child(3) {
        border-left: 0;
        border-top:1px solid var(--line)
    }

    .hero-stats div:nth-child(4) {
        border-top:1px solid var(--line)
    }

    .section {
        padding:85px 0
    }

    .video-section {
        padding-top:100px
    }

    .video-frame {
        height:410px
    }

    .logo-row {
        grid-template-columns: repeat(3, 1fr);
        gap:28px 15px
    }

    .logo-row > span:nth-child(n + 4) {
        transform:translate(50%)
    }

    .testimonial-grid, .split-heading, .studies-grid, .contact-grid {
        grid-template-columns:1fr
    }

    .split-heading {
        gap:22px
    }

    .studies-grid {
        margin-inline: auto;
        max-width: 520px;
        margin-top:50px
    }

    .study-card {
        min-height:440px
    }

    .contact-grid {
        gap:60px
    }

    .contact-copy {
        max-width:590px
    }

    .footer-top {
        grid-template-columns:1fr auto
    }

    .footer-links {
        grid-area:2/1/auto/-1
    }
}

@media (width<=560px) {
    .container {
        width:calc(100% - 28px)
    }

    .brand strong {
        font-size:20px
    }

    .brand-mark {
        width: 32px;
        height:39px
    }

    .hero {
        padding-top:56px
    }

    .hero h1 {
        font-size:43px
    }

    .hero-sub {
        font-size:17px
    }

    .hero-actions {
        flex-direction: column;
        gap:18px
    }

    .hero-actions .button {
        width:100%
    }

    .hero-visual {
        min-height: 390px;
        margin-inline:-10px
    }

    .orbit-one {
        width: 370px;
        height:370px
    }

    .orbit-two {
        width: 290px;
        height:290px
    }

    .dashboard-card {
        width: 310px;
        transform:none
    }

    .dashboard-body {
        padding:17px
    }

    .hero-card {
        padding:10px
    }

    .status-card {
        top: 27px;
        right:1px
    }

    .help-card {
        bottom: 20px;
        left:0
    }

    .hero-card strong {
        font-size:16px
    }

    .status-icon, .help-icon {
        width: 31px;
        height:31px
    }

    .hero-stats div {
        padding:20px
    }

    .hero-stats strong {
        font-size:20px
    }

    .section {
        padding:72px 0
    }

    .section-heading h2, .split-heading h2, .contact-copy h2 {
        font-size:38px
    }

    .video-frame {
        border-width: 5px;
        height:290px
    }

    .play-button {
        width: 64px;
        height:64px
    }

    .video-caption {
        bottom: 16px;
        left:18px
    }

    .video-caption strong {
        font-size:16px
    }

    .placeholder-note {
        line-height:1.5
    }

    .proof-section {
        padding:62px 0 75px
    }

    .logo-row {
        grid-template-columns:1fr 1fr
    }

    .logo-row > span:nth-child(n + 4) {
        transform:none
    }

    .logo-row > span:last-child {
        grid-column:1/-1
    }

    .testimonial-grid {
        margin-top:50px
    }

    .testimonial-featured, .testimonial-mini {
        padding:26px
    }

    .testimonial-featured blockquote {
        font-size:19px
    }

    .testimonial-featured footer {
        flex-wrap:wrap
    }

    .testimonial-featured footer .stars {
        width: 100%;
        margin:5px 0 0 55px
    }

    .steps-grid {
        grid-template-columns:1fr
    }

    .step-card + .step-card {
        border-left: 0;
        border-top:1px solid var(--line)
    }

    .step-card {
        min-height:300px
    }

    .steps-cta {
        flex-direction: column;
        align-items: stretch;
        gap:22px
    }

    .steps-cta .button {
        width:100%
    }

    .study-result strong {
        font-size:49px
    }

    .contact-faq {
        padding:27px 20px
    }

    .faq-item button {
        font-size:16px
    }

    .footer-top {
        grid-template-columns: 1fr;
        gap:32px
    }

    .footer-links {
        flex-wrap: wrap;
        grid-area: auto;
        gap:20px 25px
    }

    .footer-top > .button {
        width:max-content
    }

    .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
        gap:13px
    }

    .footer-bottom p:last-child {
        flex-wrap:wrap
    }
}

@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior:auto
    }

    *, :before, :after {
        transition-duration:.01ms !important
    }
}

